/**
 * Official Command & Conquer: Generals Authentic Audio & Voice Responses
 * Extracted directly from retail Audio.big and AudioEnglish.big
 */
window.OFFICIAL_AUDIO_DATA = {"sfx_cannon_crusader":"data:audio/wav;base64,","sfx_cannon_paladin":"data:audio/wav;base64,","sfx_rifle_ranger":"data:audio/wav;base64,","sfx_missile_comanche":"data:audio/wav;base64,","sfx_missile_tomahawk":"data:audio/wav;base64,","sfx_explosion":"data:audio/wav;base64,","sfx_click":"data:audio/wav;base64,","voice_crusader_select":"data:audio/wav;base64,","voice_crusader_move":"data:audio/wav;base64,","voice_crusader_attack":"data:audio/wav;base64,","voice_paladin_select":"data:audio/wav;base64,","voice_paladin_move":"data:audio/wav;base64,","voice_paladin_attack":"data:audio/wav;base64,","voice_ranger_create":"data:audio/wav;base64,","voice_ranger_select":"data:audio/wav;base64,","voice_ranger_move":"data:audio/wav;base64,","voice_ranger_attack":"data:audio/wav;base64,","voice_humvee_select":"data:audio/wav;base64,","voice_humvee_move":"data:audio/wav;base64,","voice_humvee_attack":"data:audio/wav;base64,","voice_comanche_select":"data:audio/wav;base64,","voice_comanche_move":"data:audio/wav;base64,","voice_comanche_attack":"data:audio/wav;base64,","voice_chinook_select":"data:audio/wav;base64,","voice_chinook_move":"data:audio/wav;base64,","voice_raptor_select":"data:audio/wav;base64,","voice_raptor_move":"data:audio/wav;base64,","voice_raptor_attack":"data:audio/wav;base64,","voice_aurora_select":"data:audio/wav;base64,","voice_aurora_move":"data:audio/wav;base64,","voice_aurora_attack":"data:audio/wav;base64,","voice_dozer_select":"data:audio/wav;base64,","voice_dozer_move":"data:audio/wav;base64,","voice_dozer_build":"data:audio/wav;base64,","voice_burton_select":"data:audio/wav;base64,","voice_burton_move":"data:audio/wav;base64,","voice_burton_attack":"data:audio/wav;base64,","voice_pathfinder_select":"data:audio/wav;base64,","voice_pathfinder_move":"data:audio/wav;base64,","voice_pathfinder_attack":"data:audio/wav;base64,"};
window.OFFICIAL_AUDIO_CACHE = {};

function playOfficialSound(soundKey, volume = 0.8) {
    if (!window.OFFICIAL_AUDIO_DATA || !window.OFFICIAL_AUDIO_DATA[soundKey]) return;
    try {
        const audio = new Audio(window.OFFICIAL_AUDIO_DATA[soundKey]);
        audio.volume = Math.max(0, Math.min(1, volume));
        audio.play().catch(() => {});
    } catch (e) {}
}

function playUnitVoice(unitType, action = 'select') {
    const t = (unitType || '').toLowerCase();
    let key = '';
    if (t === 'crusader' || t === 'tank') key = 'voice_crusader_' + action;
    else if (t === 'paladin') key = 'voice_paladin_' + action;
    else if (t === 'ranger' || t === 'infantry') key = 'voice_ranger_' + action;
    else if (t === 'humvee') key = 'voice_humvee_' + action;
    else if (t === 'comanche') key = 'voice_comanche_' + action;
    else if (t === 'chinook') key = 'voice_chinook_' + (action === 'attack' ? 'move' : action);
    else if (t === 'raptor') key = 'voice_raptor_' + action;
    else if (t === 'aurora') key = 'voice_aurora_' + action;
    else if (t === 'dozer') key = 'voice_dozer_' + (action === 'attack' ? 'move' : action);
    else if (t === 'burton') key = 'voice_burton_' + action;
    else if (t === 'pathfinder') key = 'voice_pathfinder_' + action;

    if (key && window.OFFICIAL_AUDIO_DATA && window.OFFICIAL_AUDIO_DATA[key]) {
        playOfficialSound(key, 0.85);
    }
}
window.playOfficialSound = playOfficialSound;
window.playUnitVoice = playUnitVoice;
